 if not epochs or any(type(x)is not int or x<1 for x in epochs):raise ValueError('known positive epochs required')
 epoch=max(epochs)+1
 if epoch>9007199254740991:raise ValueError('unsafe epoch')
 result=wrap(source,output,epoch)
 pointer=json.loads((output/'release-channel.json').read_text());pointer['rollback']=True
 (output/'rollback-channel.json').write_text(json.dumps(pointer,sort_keys=True,indent=2)+'\n')
 (output/'release-channel.json').unlink()
 (output/'R0-NOT-ACTIVE.json').write_text(json.dumps({'role':'prepared-rollback-only','generation':result['generation'],'knownEpochs':epochs,'proposedEpoch':epoch,'limitations':['Not automatically selected','Epoch must be rechecked against current channel and clients before use','Real application and FCM not certified']},indent=2)+'\n')
 return {**result,'epoch':epoch,'selected':False}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--output',required=True);p.add_argument('--known-epochs',required=True);a=p.parse_args();print(json.dumps(prepare(a.source,a.output,[int(x)for x in a.known_epochs.split(',')])))

