/* Read-only JS dependency scanner. Acorn is supplied by the local lint toolchain. */
const fs = require('node:fs');
const acorn = require(process.env.RELEASE_ACORN || '/usr/lib/node_modules/eslint/node_modules/acorn');
const source = fs.readFileSync(process.argv[2] === '-' ? 0 : process.argv[2], 'utf8');
let ast;
try { ast = acorn.parse(source, {ecmaVersion: 'latest', sourceType: 'module', locations: true}); }
catch (error) { console.log(JSON.stringify({error: error.message})); process.exit(0); }
const imports = [], unresolved = [], runtime = [];
function visit(node) {
  if (!node || typeof node !== 'object') return;
  const literal = n => n && typeof n.value === 'string' ? n.value : null;
  if (['ImportDeclaration','ExportNamedDeclaration','ExportAllDeclaration'].includes(node.type) && node.source)
    imports.push({specifier:node.source.value,line:node.loc.start.line,kind:'static'});
  if (node.type === 'ImportExpression') {
    const value=literal(node.source);
    if(value !== null) imports.push({specifier:value,line:node.loc.start.line,kind:'dynamic-literal'});
    else unresolved.push({expression:source.slice(node.source.start,node.source.end),line:node.loc.start.line,kind:'dynamic-expression'});
  }
  if (node.type === 'CallExpression' && node.callee?.type==='Identifier' && node.callee.name==='importScripts') {
    for(const arg of node.arguments) {
      const value=literal(arg);
      if(value !== null) imports.push({specifier:value,line:node.loc.start.line,kind:'worker-import'});
      else unresolved.push({expression:source.slice(arg.start,arg.end),line:node.loc.start.line,kind:'worker-expression'});
    }
  }
  if(node.type==='AssignmentExpression' && node.left?.type==='MemberExpression' && ['src','href'].includes(node.left.property?.name)) {
    const value=literal(node.right);
    if(value !== null && !/^(https?:|data:|blob:|#)/i.test(value)) runtime.push({value,line:node.loc.start.line,kind:'document-relative-assignment'});
  }
  for(const [key,value] of Object.entries(node)) {
    if(['loc','start','end'].includes(key)) continue;
    if(Array.isArray(value)) value.forEach(visit); else if(value && typeof value==='object') visit(value);
  }
}
visit(ast);
console.log(JSON.stringify({imports,unresolved,runtime}));

