"""Bind shell identity data only; never rewrite worker executable logic."""
import hashlib,json,re

def digest(data):return hashlib.sha256(data).hexdigest()
def bind(worker,shell,bridge,version='production',static=None):
 pattern=rb'const GW_SHELL = .*?;\n'
 matches=list(re.finditer(pattern,worker))
 if len(matches)!=1:raise ValueError('one shell identity declaration required')
 core=re.sub(pattern,b'const GW_SHELL = null;\n',worker)
 identity={'schema':1,'shellSHA256':digest(shell),'bridgeSHA256':digest(bridge),'version':str(version)}
 if static:identity['static']={key:{'sha256':digest(body),'contentType':{'css':'text/css','json':'application/json','png':'image/png'}[key.rsplit('.',1)[-1]]}for key,body in sorted(static.items())}
 identity['engine']=digest(core+json.dumps(identity,sort_keys=True,separators=(',',':')).encode())
 declaration=b'const GW_SHELL = '+json.dumps(identity,sort_keys=True,separators=(',',':')).encode()+b';\n'
 result=re.sub(pattern,lambda _:declaration,worker)
 if re.sub(pattern,b'',result)!=re.sub(pattern,b'',worker):raise ValueError('executable logic changed')
 return result,identity
